drills.solutionHead:
// ─────────────────────────────────────────────────────────────────────────
//  01 · compose a middleware pipeline★★★ core
//  concepts: delegates · composition · ordering
// ─────────────────────────────────────────────────────────────────────────
//
//  Build from the terminal backwards: the first registered ends up outermost.

using static Bootcamp.Check;

RequestDelegate Build(IReadOnlyList<Func<RequestDelegate, RequestDelegate>> middleware, RequestDelegate terminal)
{
    var app = terminal;
    for (var i = middleware.Count - 1; i >= 0; i--) app = middleware[i](app);
    return app;
}

Func<RequestDelegate, RequestDelegate> Logger(string name) => next => async ctx =>
{
    ctx.Log.Add(name + " in");
    await next(ctx);
    ctx.Log.Add(name + " out");
};

drills.tests:
// ──────────────────────────── tests ──────────────────────────────────────

Test("the first registered middleware is outermost", async () =>
{
    var app = Build(new[] { Logger("A"), Logger("B") }, ctx => { ctx.Log.Add("endpoint"); return Task.CompletedTask; });
    var ctx = new Context("/x");
    await app(ctx);
    Eq(ctx.Log, new[] { "A in", "B in", "endpoint", "B out", "A out" });
});

Test("a middleware can short-circuit", async () =>
{
    Func<RequestDelegate, RequestDelegate> limiter = next => ctx => { ctx.Status = 429; return Task.CompletedTask; };
    var app = Build(new[] { Logger("A"), limiter, Logger("B") }, ctx => { ctx.Log.Add("endpoint"); return Task.CompletedTask; });
    var ctx = new Context("/x");
    await app(ctx);
    Eq(ctx.Status, 429);
    Eq(ctx.Log, new[] { "A in", "A out" });
});

Test("middleware can branch on the request", async () =>
{
    Func<RequestDelegate, RequestDelegate> health = next => ctx => ctx.Path == "/health" ? Task.Run(() => ctx.Status = 204) : next(ctx);
    var app = Build(new[] { health }, ctx => { ctx.Status = 200; return Task.CompletedTask; });
    var h = new Context("/health");
    var o = new Context("/orders");
    await app(h);
    await app(o);
    Eq((h.Status, o.Status), (204, 200));
});

Test("no middleware means the terminal handler alone (boundary)", async () =>
{
    var app = Build(Array.Empty<Func<RequestDelegate, RequestDelegate>>(), ctx => { ctx.Log.Add("endpoint"); return Task.CompletedTask; });
    var ctx = new Context("/");
    await app(ctx);
    Eq(ctx.Log, new[] { "endpoint" });
});

Test("exceptions propagate to the caller", async () =>
{
    var app = Build(new[] { Logger("A") }, _ => throw new InvalidOperationException("boom"));
    await ThrowsAsync<InvalidOperationException>(() => app(new Context("/")));
});

